-- v2 编号 0262；移植自 main 0238_channel_signature_profiles（main 6f54290f，B9），见 docs/main-v2-sync.md。
ALTER TABLE channels ADD COLUMN signature_profiles boolean NOT NULL DEFAULT false;
ALTER TABLE channels ADD CONSTRAINT channel_signature_profiles_check CHECK (NOT signature_profiles OR (signatures AND broadcast AND NOT megagroup));
-- Visibility is immutable per message; old anonymous posts must stay anonymous.
ALTER TABLE channel_messages ADD COLUMN show_message_sender boolean NOT NULL DEFAULT false;
ALTER TABLE channel_admin_log_events DROP CONSTRAINT channel_admin_log_events_type_check;
ALTER TABLE channel_admin_log_events ADD CONSTRAINT channel_admin_log_events_type_check CHECK (((event_type)::text = ANY (ARRAY[('change_title'::character varying)::text, ('change_username'::character varying)::text, ('change_linked_chat'::character varying)::text, ('toggle_signatures'::character varying)::text, ('toggle_pre_history_hidden'::character varying)::text, ('toggle_forum'::character varying)::text, ('toggle_autotranslation'::character varying)::text, ('toggle_anti_spam'::character varying)::text, ('toggle_slow_mode'::character varying)::text, ('participant_invite'::character varying)::text, ('participant_join'::character varying)::text, ('participant_leave'::character varying)::text, ('participant_promote'::character varying)::text, ('participant_demote'::character varying)::text, ('participant_edit_rank'::character varying)::text, ('participant_ban'::character varying)::text, ('participant_unban'::character varying)::text, ('participant_kick'::character varying)::text, ('participant_unkick'::character varying)::text, ('update_pinned'::character varying)::text, ('send_message'::character varying)::text, ('edit_message'::character varying)::text, ('delete_message'::character varying)::text])) OR event_type = 'toggle_signature_profiles');
